    public function setTransferencias(PropelCollection $transferencias, PropelPDO $con = null)
    {
        $transferenciasToDelete = $this->getTransferencias(new Criteria(), $con)->diff($transferencias);


        $this->transferenciasScheduledForDeletion = $transferenciasToDelete;

        foreach ($transferenciasToDelete as $transferenciaRemoved) {
            $transferenciaRemoved->setFactura(null);
        }

        $this->collTransferencias = null;
        foreach ($transferencias as $transferencia) {
