    public function countTransferencias(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collTransferenciasPartial && !$this->isNew();
        if (null === $this->collTransferencias || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collTransferencias) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getTransferencias());
            }
            $query = TransferenciaQuery::create(null, $criteria);
            if ($distinct) {
