    public function addTransferencia(Transferencia $l)
    {
        if ($this->collTransferencias === null) {
            $this->initTransferencias();
            $this->collTransferenciasPartial = true;
        }

        if (!in_array($l, $this->collTransferencias->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddTransferencia($l);

            if ($this->transferenciasScheduledForDeletion and $this->transferenciasScheduledForDeletion->contains($l)) {
                $this->transferenciasScheduledForDeletion->remove($this->transferenciasScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

