    /**
     * @param	Transferencia $transferencia The transferencia object to remove.
     * @return Factura The current object (for fluent API support)
     */
    public function removeTransferencia($transferencia)
    {
        if ($this->getTransferencias()->contains($transferencia)) {
            $this->collTransferencias->remove($this->collTransferencias->search($transferencia));
            if (null === $this->transferenciasScheduledForDeletion) {
                $this->transferenciasScheduledForDeletion = clone $this->collTransferencias;
                $this->transferenciasScheduledForDeletion->clear();
            }
            $this->transferenciasScheduledForDeletion[]= $transferencia;
            $transferencia->setFactura(null);
        }

        return $this;
    }


