            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collFactVariableValuess) {
                foreach ($this->collFactVariableValuess as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collFacturaAuditImages) {
                foreach ($this->collFacturaAuditImages as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collFacturaVitacoras) {
                foreach ($this->collFacturaVitacoras as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTransferencias) {
                foreach ($this->collTransferencias as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aProveedor instanceof Persistent) {
              $this->aProveedor->clearAllReferences($deep);
            }
            if ($this->aRegional instanceof Persistent) {
              $this->aRegional->clearAllReferences($deep);
            }
            if ($this->aPeriodo instanceof Persistent) {
